import time

from taf.config.testline.pdu import PduPort

from .pdu_factory import PduFactory
from .devices.base import PduIdentInfo


class PduFacade(object):
    def setup_pdu(self, model, host, **kwargs):
        device = PduFactory.create(model=model, host=host, **kwargs)
        return device

    def power_on(self, port, pdu_device):
        if self._pdu_port_has_reversed_logic(port):
            return pdu_device.power_off(port=self._port_no(port))
        return pdu_device.power_on(port=self._port_no(port))

    def power_off(self, port, pdu_device):
        if self._pdu_port_has_reversed_logic(port):
            return pdu_device.power_on(port=self._port_no(port))
        return pdu_device.power_off(port=self._port_no(port))

    def get_port_status(self, port, pdu_device):
        inverted_statuses = {"on": "off", "off": "on"}
        status = pdu_device.get_port_status(port=self._port_no(port))
        return inverted_statuses.get(status, status) if self._pdu_port_has_reversed_logic(port) else status

    def reset_ports(self, ports, time_interval, pdu_device):
        if not ports:
            return pdu_device.reset(ports=ports, time_interval=time_interval)

        reversed_logic_ports = [self._port_no(port) for port in ports if self._pdu_port_has_reversed_logic(port)]
        normal_ports = [self._port_no(port) for port in ports if not self._pdu_port_has_reversed_logic(port)]
        responses = []

        if normal_ports:
            responses.append(pdu_device.reset(ports=normal_ports, time_interval=time_interval))

        if reversed_logic_ports:
            for port in reversed_logic_ports:
                responses.append(pdu_device.power_on(port=self._port_no(port)))
            time.sleep(time_interval)
            for port in reversed_logic_ports:
                responses.append(pdu_device.power_off(port=self._port_no(port)))

        return responses if any(responses) else None

    def get_voltage(self, pdu_device, port=None):
        return pdu_device.get_voltage(port=port)

    def set_voltage(self, port, voltage, pdu_device):
        return pdu_device.set_voltage(port=port, voltage=voltage)

    def teardown_pdu(self, pdu_device):
        return pdu_device.teardown()

    def get_current(self, port, pdu_device):
        """
        Get current value for a given power outlet (port)

        :param int port: port number
        :param PDU pdu_device: alias of configured pdu
        :return: electric current value in amperes (A)
        :rtype: float
        """
        return pdu_device.get_current(port)

    def get_energy_consumption(self, port, pdu_device):
        """
        Get total power consumption for a given power outlet (port)

        :param int port: port number
        :param PDU pdu_device: configured pdu class
        :return: total energy consumption in kilowatt-hours (kWh)
        :rtype: float
        """
        return pdu_device.get_energy_consumption(port)

    def get_pdu_info(self, pdu_device) -> PduIdentInfo:
        """
        Get identification information for a PDU device.

        :param str pdu_device: alias of configured pdu
        :return: PduIdentInfo(identifier, identification_type)
        :rtype: PduIdentInfo
        """
        return pdu_device.get_pdu_info()

    @staticmethod
    def _pdu_port_has_reversed_logic(port):
        if isinstance(port, PduPort):
            contactor = port.contactor
            if contactor not in ["NORMALLY_OPENED", "NORMALLY_CLOSED"]:
                raise ValueError("Unknown PduPort.contactor value, expected NORMALLY_OPENED or NORMALLY_CLOSED")
            return True if contactor == "NORMALLY_CLOSED" else False
        return False

    @staticmethod
    def _port_no(port):
        if isinstance(port, PduPort):
            port = port.port_no
        return int(port)
